/// The colour [`GOLD_LIFT_ANCHOR`] names, or `None` if [`ALL`] has no
/// such entry.
#[must_use]
pub fn lift_anchor() -> Option<Color> {
    ALL.iter()
        .find(|(name, _, _)| *name == GOLD_LIFT_ANCHOR)
        .map(|(_, color, _)| *color)
}

/// The colour [`GOLD_SHADE_ANCHOR`] names, or `None` if [`ALL`] has no
